INSERT INTO "EDUTECH".DBO.AVALIACOES
    (ID, NOTA, COMENTARIO, DATA_AVALIACAO, ID_CURSO, ID_MATRICULA)
VALUES
(1, 3, 'Pariatur numquam eveniet. Odit labore temporibus odit consectetur nisi voluptate. Mollitia eos officia ea odio blanditiis ipsum ducimus.', '2024-05-15T10:50:49', 9, 31),
(2, 1, 'At ea culpa nobis occaecati vel. Eligendi ut necessitatibus aspernatur perferendis eaque.', '2023-03-24T22:20:06', 6, 10),
(3, 5, 'Reiciendis eveniet deleniti. Beatae vitae veniam modi vero ullam quam. Blanditiis doloremque dolorem. Corrupti possimus dolores atque odio exercitationem similique. Ducimus quisquam maiores amet.', '2023-12-30T09:29:07', 13, 50),
(4, 2, 'Eius eligendi qui sint nulla explicabo magni facilis. Vel nulla a similique eum. Earum aperiam aspernatur. Rerum voluptatum natus molestiae delectus cum eos laboriosam.', '2024-02-19T22:49:04', 13, 50),
(5, 2, 'Cupiditate nisi reprehenderit modi. Libero labore earum corrupti in impedit. Eum repellendus qui distinctio. Voluptates voluptatibus eius voluptate placeat.', '2024-04-08T19:52:25', 14, 12),
(6, 1, 'Et reiciendis quod nostrum alias assumenda. Illo non eaque consectetur architecto. Quas cum occaecati neque dignissimos incidunt qui. Aut aut ullam sint eveniet.', '2025-04-12T08:36:57', 19, 69),
(7, 2, 'Et dolor non natus nemo. Officia soluta corporis incidunt id sed. Quasi sequi maiores fugit. Impedit perspiciatis dolores aperiam inventore quasi. Accusamus voluptatem tenetur.', '2024-10-27T02:04:05', 16, 70),
(8, 2, 'Maiores repudiandae porro magnam veniam. Illo asperiores repudiandae distinctio blanditiis impedit provident. Harum blanditiis suscipit.', '2023-05-31T06:44:44', 4, 14),
(9, 4, 'Soluta reprehenderit labore nostrum necessitatibus eveniet illo deleniti. Sint assumenda facilis autem. Autem ullam odio quisquam reprehenderit perspiciatis quo.', '2025-07-14T15:29:49', 19, 69),
(10, 3, 'Modi fuga aliquam aspernatur. Incidunt porro at. Repudiandae sequi inventore cupiditate dolorem error. Similique repellendus nihil modi quibusdam. Vero vero atque fugiat. Animi eos voluptatum illum.', '2023-02-21T05:35:59', 9, 58),
(11, 1, 'Unde dolore incidunt. Nemo provident maiores impedit impedit provident error. Vero inventore esse. Non atque ullam adipisci totam magni omnis.', '2025-05-22T09:50:12', 3, 68),
(12, 1, 'Ut natus magnam facilis iure vel. Aspernatur porro reprehenderit quibusdam quibusdam aperiam.', '2025-03-24T14:30:31', 16, 17),
